create or replace view LDL_DATA_PRODUCTION.META.V_DV_ACTIVE_STORE_ATTRIBUTES(
	INT_ORG_SID,
	DWH_VALID_FROM_TMSP,
	DWH_VALID_TO_TMSP,
	DWH_VALID_FG,
	CURR_INT_ORG_NR,
	INIT_INT_ORG_NR,
	INT_ORG_NAME,
	INT_ORG_STATUS_CD,
	INT_ORG_STATUS_DESCR,
	OPEN_DT,
	PLANNED_OPEN_DT,
	CLOSE_DT,
	ISO_COUNTRY_CD,
	COUNTRY_NAME,
	CITY_NAME,
	DISTRICT_NAME,
	ZIP,
	STREET_NAME,
	HOUSE_NR,
	LON,
	LAT,
	PO_BOX_NR,
	PHONE_NR,
	FAX_NR,
	EMAIL_ADDR_TXT,
	REPORTING_COUNTRY_CD,
	SALES_MGR_DISTRICT_SID,
	SALES_MGR_DISTRICT_NR,
	SALES_MGR_DISTRICT_NAME,
	SALES_MGR_EMP_SID,
	SALES_MGR_EMP_NR,
	SALES_MGR_NAME,
	ACCT_MGR_DISTRICT_SID,
	ACCT_MGR_DISTRICT_NR,
	ACCT_MGR_DISTRICT_NAME,
	ACCT_MGR_EMP_SID,
	ACCT_MGR_EMP_NR,
	ACCT_MGR_NAME,
	SALES_COMPANY_SID,
	SALES_COMPANY_NR,
	SALES_COMPANY_NAME,
	SALES_COMPANY_DIRECTOR_EMP_SID,
	SALES_COMPANY_DIRECTOR_EMP_NR,
	SALES_COMPANY_DIRECTOR_NAME,
	DELIV_COMPANY_SID,
	DELIV_COMPANY_NR,
	DELIV_COMPANY_NAME,
	DELIV_COMPANY_DIRECTOR_EMP_SID,
	DELIV_COMPANY_DIRECTOR_EMP_NR,
	DELIV_COMPANY_DIRECTOR_NAME,
	EXPANSION_COMPANY_SID,
	EXPANSION_COMPANY_NR,
	EXPANSION_COMPANY_NAME,
	BAL_SHEET_COMPANY_SID,
	BAL_SHEET_COMPANY_NR,
	BAL_SHEET_COMPANY_NAME,
	OWNER_COMPANY_SID,
	OWNER_COMPANY_NR,
	OWNER_COMPANY_NAME,
	SALES_REGION_SID,
	SALES_REGION_NR,
	SALES_REGION_NAME,
	SALES_REGION_MGR_EMP_SID,
	SALES_REGION_MGR_EMP_NR,
	SALES_REGION_MGR_NAME,
	DELIV_REGION_SID,
	DELIV_REGION_NR,
	DELIV_REGION_NAME,
	DELIV_REGION_MGR_EMP_SID,
	DELIV_REGION_MGR_EMP_NR,
	DELIV_REGION_MGR_NAME,
	COUNTRY_ORG_SID,
	COUNTRY_ORG_CD,
	COUNTRY_ORG_NR,
	COUNTRY_ORG_NAME,
	COUNTRY_ORG_MGR_EMP_SID,
	COUNTRY_ORG_MGR_EMP_NR,
	COUNTRY_ORG_MGR_NAME,
	COUNTRY_GRP_ORG_SID,
	COUNTRY_GRP_ORG_NR,
	COUNTRY_GRP_ORG_NAME,
	COUNTRY_GRP_ORG_MGR_EMP_SID,
	COUNTRY_GRP_ORG_MGR_EMP_NR,
	COUNTRY_GRP_ORG_MGR_NAME,
	DWH_CREATED_TMSP,
	DWH_UPDATED_TMSP,
	DWH_LOAD_ID,
	DWH_NODE_CD,
	SC_SALES_COMPANY_SID,
	SC_SALES_COMPANY_NAME,
	CNTR_COUNTRY_ORG_SID,
	CNTR_COUNTRY_ORG_NAME,
	OH_STORE_SID,
	REAL_ESTATE_SID,
	REAL_ESTATE_NR,
	REAL_ESTATE_NAME,
	REAL_ESTATE_STATUS_CD,
	REAL_ESTATE_TYPE_CD,
	FAILED_SALES_MANAGER_VALID,
	FAILED_ACCOUNT_MANAGER_VALID,
	FAILED_SALES_COMPANY_VALID,
	FAILED_SALES_COMPANY_CONSISTENT,
	FAILED_COUNTRY_ORG_VALID,
	FAILED_COUNTRY_ORG_CONSISTENT,
	FAILED_REAL_ESTATE_TERMINATED,
	FAILED_REAL_ESTATE_MISSING,
	FAILED_MISSING_OPENING_HOURS,
	TOTAL
) COMMENT='Active stores from core_dim.t_dim_internal_organization and related attributes (managers, sales company, country, opening_hours, estate_type_cd..)\ninput datasets:\ncore_dim.t_dim_internal_organization\ncore_dim.t_dim_real_estate\ncore_rel.t_store_opening_hours'
 as select store.INT_ORG_SID, store.DWH_VALID_FROM_TMSP, store.DWH_VALID_TO_TMSP, store.DWH_VALID_FG, store.CURR_INT_ORG_NR, store.INIT_INT_ORG_NR, store.INT_ORG_NAME, store.INT_ORG_STATUS_CD, store.INT_ORG_STATUS_DESCR, store.OPEN_DT, store.PLANNED_OPEN_DT, store.CLOSE_DT, store.ISO_COUNTRY_CD, store.COUNTRY_NAME, store.CITY_NAME, store.DISTRICT_NAME, store.ZIP, store.STREET_NAME, store.HOUSE_NR, store.LON, store.LAT, store.PO_BOX_NR, store.PHONE_NR, store.FAX_NR, store.EMAIL_ADDR_TXT, store.REPORTING_COUNTRY_CD, store.SALES_MGR_DISTRICT_SID, store.SALES_MGR_DISTRICT_NR, store.SALES_MGR_DISTRICT_NAME, store.SALES_MGR_EMP_SID, store.SALES_MGR_EMP_NR, store.SALES_MGR_NAME, store.ACCT_MGR_DISTRICT_SID, store.ACCT_MGR_DISTRICT_NR, store.ACCT_MGR_DISTRICT_NAME, store.ACCT_MGR_EMP_SID, store.ACCT_MGR_EMP_NR, store.ACCT_MGR_NAME, store.SALES_COMPANY_SID, store.SALES_COMPANY_NR, store.SALES_COMPANY_NAME, store.SALES_COMPANY_DIRECTOR_EMP_SID, store.SALES_COMPANY_DIRECTOR_EMP_NR, store.SALES_COMPANY_DIRECTOR_NAME, store.DELIV_COMPANY_SID, store.DELIV_COMPANY_NR, store.DELIV_COMPANY_NAME, store.DELIV_COMPANY_DIRECTOR_EMP_SID, store.DELIV_COMPANY_DIRECTOR_EMP_NR, store.DELIV_COMPANY_DIRECTOR_NAME, store.EXPANSION_COMPANY_SID, store.EXPANSION_COMPANY_NR, store.EXPANSION_COMPANY_NAME, store.BAL_SHEET_COMPANY_SID, store.BAL_SHEET_COMPANY_NR, store.BAL_SHEET_COMPANY_NAME, store.OWNER_COMPANY_SID, store.OWNER_COMPANY_NR, store.OWNER_COMPANY_NAME, store.SALES_REGION_SID, store.SALES_REGION_NR, store.SALES_REGION_NAME, store.SALES_REGION_MGR_EMP_SID, store.SALES_REGION_MGR_EMP_NR, store.SALES_REGION_MGR_NAME, store.DELIV_REGION_SID, store.DELIV_REGION_NR, store.DELIV_REGION_NAME, store.DELIV_REGION_MGR_EMP_SID, store.DELIV_REGION_MGR_EMP_NR, store.DELIV_REGION_MGR_NAME, store.COUNTRY_ORG_SID, store.COUNTRY_ORG_CD, store.COUNTRY_ORG_NR, store.COUNTRY_ORG_NAME, store.COUNTRY_ORG_MGR_EMP_SID, store.COUNTRY_ORG_MGR_EMP_NR, store.COUNTRY_ORG_MGR_NAME, store.COUNTRY_GRP_ORG_SID, store.COUNTRY_GRP_ORG_NR, store.COUNTRY_GRP_ORG_NAME, store.COUNTRY_GRP_ORG_MGR_EMP_SID, store.COUNTRY_GRP_ORG_MGR_EMP_NR, store.COUNTRY_GRP_ORG_MGR_NAME, store.DWH_CREATED_TMSP, store.DWH_UPDATED_TMSP, store.DWH_LOAD_ID, store.DWH_NODE_CD, sales_company.int_org_sid as sc_sales_company_sid, sales_company.int_org_name as sc_sales_company_name, country_org.int_org_sid as cntr_country_org_sid, country_org.country_name as cntr_country_org_name, oh.store_sid as oh_store_sid, re.real_estate_sid, re.real_estate_nr, re.real_estate_name, re.real_estate_status_cd, re.real_estate_type_cd, CASE WHEN lower(store.sales_mgr_name) = 'unbekannt' THEN 1 ELSE 0 END AS FAILED_SALES_MANAGER_VALID, CASE WHEN lower(store.acct_mgr_name) = 'unbekannt' THEN 1 ELSE 0 END AS FAILED_ACCOUNT_MANAGER_VALID, CASE WHEN lower(store.sales_company_name) = 'unbekannt' THEN 1 ELSE 0 END AS FAILED_SALES_COMPANY_VALID, CASE WHEN sc_sales_company_name is null or store.sales_company_name != sc_sales_company_name THEN 1 ELSE 0 END AS FAILED_SALES_COMPANY_CONSISTENT, CASE WHEN lower(store.country_org_name) = 'unbekannt' THEN 1 ELSE 0 END AS FAILED_COUNTRY_ORG_VALID, CASE WHEN cntr_country_org_name is null or store.country_org_name != cntr_country_org_name THEN 1 ELSE 0 END AS FAILED_COUNTRY_ORG_CONSISTENT, CASE WHEN (re.real_estate_status_cd = 'TE' AND re.real_estate_status_cd IS NOT NULL) THEN 1 ELSE 0 END AS FAILED_REAL_ESTATE_TERMINATED, CASE WHEN (re.real_estate_status_cd IS NULL) THEN 1 ELSE 0 END AS FAILED_REAL_ESTATE_MISSING, CASE WHEN (re.real_estate_type_cd = 'STORE' and oh.store_sid IS NULL) THEN 1 ELSE 0 END AS FAILED_MISSING_OPENING_HOURS, 1 AS TOTAL from core_dim.t_dim_internal_organization store left join ( select int_org_sid, int_org_name from core_dim.t_dim_internal_organization where dwh_valid_fg = true and int_org_type_cd = 'COMPANY' and lower(int_org_status_cd) = 'active' and is_sales_company_fg = true ) sales_company on sales_company.int_org_sid = store.sales_company_sid left join ( select int_org_sid, country_name from core_dim.t_dim_internal_organization where dwh_valid_fg = true and int_org_type_cd = 'COMPANY' and lower(int_org_status_cd) = 'active' and is_country_org_fg = true ) country_org on country_org.int_org_sid = store.country_org_sid left join ( select distinct store_sid from core_rel.t_store_opening_hours where dwh_valid_fg = true ) oh on oh.store_sid = store.int_org_sid left join core_dim.t_dim_real_estate re on re.int_org_sid = store.int_org_sid and store.dwh_valid_from_tmsp between re.dwh_valid_from_tmsp and re.dwh_valid_to_tmsp where store.dwh_valid_fg = true and store.int_org_type_cd = 'STORE' and lower(store.int_org_status_cd) = 'active';